import sailpoint.api.Terminator;
import sailpoint.object.Filter;
import sailpoint.object.Link;
import sailpoint.object.QueryOptions;

        /*
         * Given a list of IDs, delete the Links for all Identities NOT in that list
         */
        String[] NO_CAN_HAS = new String[] {
                "c0a8561a999610b0819996f0e1900017",
