        Terminator thanos = new Terminator(context);
        QueryOptions ops = new QueryOptions();
        Filter inFilter = Filter.in("identity.id", Arrays.asList(NO_CAN_HAS));
        Filter nawFilter = Filter.not(inFilter);
        ops.add(nawFilter);
        int count = context.countObjects(Link.class, ops);
        log.warn("Thanos snap: Deleting " + count + " Links...");
        thanos.deleteObjects(Link.class, ops);
